void Win32IDE::initializeAutonomy() {
    if (!m_agenticBridge) {
        IDELogger::getInstance().info(__FUNCTION__, "Cannot initialize autonomy: agentic bridge not initialized");
        return;
    }
    m_autonomyManager = std::make_unique<AutonomyManager>(m_agenticBridge.get());
    IDELogger::getInstance().info(__FUNCTION__, "Autonomy manager initialized");
}
